INSERT INTO question_bank (question_text, options, correct_option, topic, difficulty, is_active) VALUES
('What problem does a circular queue solve compared to a simple linear queue implemented with an array?', '["It allows O(1) access to the middle element","It reuses empty spaces at the front after dequeues, avoiding wasted space","It allows sorting elements automatically","It removes the need for a rear pointer"]'::jsonb, 1, 'dsa', 'medium', true),
('What is the time complexity of implementing a stack using two queues, for a push operation, if push is made O(1) at the cost of a more expensive pop?', '["O(1)","O(log n)","O(n)","O(n^2)"]'::jsonb, 0, 'dsa', 'hard', true),
('What is the time complexity to check if a queue is empty?', '["O(1)","O(log n)","O(n)","O(n^2)"]'::jsonb, 0, 'dsa', 'easy', true),
('A deque (double-ended queue) allows insertion and deletion:', '["Only at the front","Only at the rear","At both the front and rear","Only at the middle"]'::jsonb, 2, 'dsa', 'medium', true),
('In a binary tree, what is the maximum number of children a node can have?', '["1","2","3","Unlimited"]'::jsonb, 1, 'dsa', 'easy', true),
('What is the time complexity of an inorder traversal of a binary tree with n nodes?', '["O(1)","O(log n)","O(n)","O(n^2)"]'::jsonb, 2, 'dsa', 'easy', true),
('What is the space complexity of a recursive inorder traversal of a skewed binary tree with n nodes, considering the call stack?', '["O(1)","O(log n)","O(n)","O(n^2)"]'::jsonb, 2, 'dsa', 'medium', true),
('Which traversal visits the root node before its left and right subtrees?', '["Inorder","Preorder","Postorder","Level-order"]'::jsonb, 1, 'dsa', 'easy', true),
('Which traversal visits the root node after its left and right subtrees?', '["Inorder","Preorder","Postorder","Level-order"]'::jsonb, 2, 'dsa', 'easy', true),
('Which data structure is used to perform a level-order traversal of a binary tree?', '["Stack","Queue","Priority queue only","Hash table"]'::jsonb, 1, 'dsa', 'medium', true),
('What is the maximum number of nodes in a binary tree of height h, where the root is at height 0?', '["2^h","2^h - 1","2^(h+1) - 1","2h + 1"]'::jsonb, 2, 'dsa', 'medium', true),
('What is the minimum possible height of a binary tree with n nodes?', '["n-1","n/2","floor(log2 n)","n"]'::jsonb, 2, 'dsa', 'hard', true),
('In a full binary tree, where every node has 0 or 2 children, if there are L leaf nodes, how many internal nodes with 2 children are there?', '["L","L-1","L+1","2L"]'::jsonb, 1, 'dsa', 'medium', true),
('What does it mean for a binary tree to be balanced?', '["All nodes have exactly two children","The height difference between left and right subtrees of every node is bounded, e.g. at most 1","All leaf nodes are at the same level always","The tree has no leaf nodes"]'::jsonb, 1, 'dsa', 'easy', true),
('What is the time complexity to find the lowest common ancestor (LCA) of two nodes in a binary tree, not necessarily a BST, using a standard recursive approach, given n nodes?', '["O(1)","O(log n)","O(n)","O(n^2)"]'::jsonb, 2, 'dsa', 'hard', true),
('Which traversal order, when combined with inorder traversal, is sufficient to uniquely reconstruct a binary tree, assuming no duplicate values?', '["Level-order only without inorder","Preorder or postorder","Only postorder combined with level-order but never preorder","None; inorder alone suffices"]'::jsonb, 1, 'dsa', 'medium', true),
('A leaf node in a binary tree is a node that has:', '["No parent","No children","Exactly one child","Two children"]'::jsonb, 1, 'dsa', 'easy', true),
('What is the time complexity to compute the height of a binary tree with n nodes?', '["O(1)","O(log n)","O(n)","O(n^2)"]'::jsonb, 2, 'dsa', 'medium', true),
('What is the worst-case auxiliary space complexity of a level-order (BFS) traversal of a binary tree with n nodes, in terms of the queue storage?', '["O(1)","O(log n)","O(h) where h is height","O(n)"]'::jsonb, 3, 'dsa', 'hard', true),
('A complete binary tree is one where:', '["Every node has exactly two children","All levels are completely filled except possibly the last, which is filled left to right","It is always a binary search tree","It has only leaf nodes at the root level"]'::jsonb, 1, 'dsa', 'easy', true),
('In a binary search tree, for any node, all values in the left subtree are:', '["Greater than the node value","Less than the node value","Equal to the node value","Unrelated to the node value"]'::jsonb, 1, 'dsa', 'easy', true),
('What is the average-case time complexity of search, insert, and delete operations in a balanced binary search tree with n nodes?', '["O(1)","O(log n)","O(n)","O(n log n)"]'::jsonb, 1, 'dsa', 'medium', true),
('What is the worst-case time complexity of search in a binary search tree that has degenerated into a skewed tree, like a linked list, with n nodes?', '["O(1)","O(log n)","O(n)","O(n log n)"]'::jsonb, 2, 'dsa', 'medium', true),
('Which traversal of a binary search tree visits nodes in sorted ascending order?', '["Preorder","Inorder","Postorder","Level-order"]'::jsonb, 1, 'dsa', 'easy', true),
('In a BST, when deleting a node with two children, it is typically replaced by:', '["Its left child directly","Its inorder successor (or predecessor)","The root of the tree","A newly created leaf node"]'::jsonb, 1, 'dsa', 'medium', true);
